TRUNCATE TABLE `team_members`;

INSERT INTO `team_members` (`name`, `role`, `group_name`, `summary`, `full_info`, `image`, `order_index`) VALUES
/* Advisory Council */
('Prof. Julia Ojiambo', 'CBS, EBS, MBS', 'Advisory Council', 'A pioneering Kenyan leader and the first Black African woman appointed as a Lecturer at the University of Nairobi’s College of Health Sciences.', 'She later earned her PhD there and became Kenya’s first female Cabinet Member. In 1976, she received the FAO Ceres Gold Medal for advancing socioeconomic empowerment for rural youth and women. She has also been honored with the President’s Awards of the Order of the Burning Spear (MBS, EBS, and CBS) for her distinguished public service and leadership in the Labour Party of Kenya.', '', 1),
('Ms Betty Adera', 'Global Health Leader', 'Advisory Council', 'A dynamic global health leader with over 20 years of experience driving impactful programs across Africa.', 'A public health expert with strong credentials (MPH, PMD, PGMD) and a PhD candidate, she brings a proven record in strategic leadership, health systems strengthening, policy advocacy, and program management.', '', 2),
('Michael Ager', 'Chief Executive Officer (C.E.O)', 'Advisory Council', 'Global Consultant in Public Relations, Governance, and Advocacy.', 'He is a passionate, results-driven expert with over a decade of experience collaborating with government agencies, UN bodies (UNDP, UNAIDS), and NGOs across national, regional, and international levels.', '', 3),
('Ms Lucy Mworia', 'HSC - CEO & Founder', 'Advisory Council', 'CEO & Founder of the Kenya Pro-Ageing organization, seconded to the Ministry of Health’s Department of Public Health.', 'She serves as a key liaison between the Ministry and implementing partners, strengthening coordination in program planning. Previously with the Ministry of Foreign and Diaspora Affairs, she brings diplomatic expertise to advocacy and partnership building. Through the Kenya Pro-Ageing Organization, she champions initiatives improving the welfare, health, and social inclusion of older persons in Kenya.', '', 4),
('Mr Bruce Tushabe', 'Regional Training Lead', 'Advisory Council', 'A Ugandan national with over 20 years of global development experience, leading Capacity Strengthening at ARASA.', 'A public health advocate and activist, he has supported governments and civil society across East and Southern Africa to advance HIV, TB, and sexual and reproductive health programs.', '', 5),
('Hon. Fred Sadia', 'Global Partnerships Strategist', 'Advisory Council', 'A distinguished global strategist connecting grassroots movements with international policy frameworks.', 'He works to advance volunteerism as a professionally managed tool for peacebuilding and sustainable development. Through strategic collaborations and cross-sector partnerships, he strengthens community-driven initiatives to align them with global priorities.', '', 6),

/* Secretariat */
('Doreen Nafula', 'Operations & Administration Manager', 'Secretariat', 'Oversees day-to-day operations and administration to ensure smooth organizational workflows.', 'She brings strong organizational skills to manage administrative processes, coordinate cross-functional teams, and support the strategic objectives of Turning Point Magazine.', '', 7),
('Moses Abuya', 'Digital Operations Lead', 'Secretariat', 'The primary architect behind the magazine\'s digital framework and seamless online experience.', 'Moses developed the Turning Point Magazine platform from scratch utilizing HTML, PHP, JavaScript, CSS, and SQL. A passionate web and Android developer, he bridges complex logic with clean user interfaces, ensuring the platform runs reliably to support the magazine\'s vision across Africa.', '', 8),
('Faith Asaka', 'Executive Assistant & Communication Officer', 'Secretariat', 'Manages executive communications and assists in streamlining internal and external correspondence.', 'She ensures clear, consistent messaging across the organization\'s channels and provides essential support to the executive team, helping to maintain efficient day-to-day operations.', '', 9),

/* Design Team */
('Shem Otina', 'Head of Design', 'Design Team', 'The Lead Creative and Communications professional guiding the magazine’s storytelling vision and creative direction.', 'He develops people-centered narratives that highlight transformative African voices and translates complex social issues into engaging, accessible content while overseeing editorial consistency, brand identity, and multimedia storytelling.', '', 10),
('Erick Otieno', 'Graphic Designer', 'Design Team', 'Translates concepts into visually compelling designs for digital and print media.', 'He supports the magazine\'s visual identity by creating engaging graphics, layouts, and illustrations that resonate with the target audience and elevate the brand\'s storytelling.', '', 11),
('Enock Otieno', 'Graphic Designer', 'Design Team', 'Creates impactful visual content to support the magazine\'s editorial and marketing efforts.', 'Dedicated to maintaining a cohesive brand aesthetic, he designs high-quality visual assets that enhance reader engagement and effectively communicate key messages.', '', 12),
('Philip Odallo', 'Graphic Designer', 'Design Team', 'Focuses on crafting innovative design solutions and engaging layouts.', 'With a keen eye for detail, he collaborates with the editorial team to produce visually striking graphics that bring Turning Point Magazine\'s stories to life.', '', 13),

/* Content Team */
('Yvonne Namiso', 'Content Creator', 'Content Team', 'Lead Journalist driving impactful storytelling that highlights accountability, social issues, and community change.', 'She is a communications specialist with a distinct passion for journalism, leveraging her platform to elevate grassroots voices and craft compelling narratives.', '', 14),
('Jackson Kahuho', 'Content Creator', 'Content Team', 'Contributes well-researched articles and narratives that align with the magazine\'s mission.', 'He focuses on identifying compelling stories and crafting engaging content that informs, inspires, and connects with readers across the continent.', '', 15),
('Esther January', 'Content Creator', 'Content Team', 'Develops engaging written content to amplify voices and highlight transformative stories.', 'She brings a strong passion for storytelling, ensuring that the magazine\'s articles are authentic, impactful, and tailored to its diverse audience.', '', 16),

/* Photography */
('Steve Andaro', 'Lead Photographer', 'Photography', 'Captures powerful visual narratives that document grassroots impact and community stories.', 'Through his lens, he provides authentic, high-quality photography that complements the magazine\'s written content and brings its transformative stories to a global audience.', '', 17),

/* Legal */
('Beryl Adhiambo', 'Legal Advisor', 'Legal', 'Provides strategic legal guidance and ensures organizational compliance.', 'She advises on media law, contracts, and regulatory matters, safeguarding the organization\'s interests and ensuring that all operations adhere to the highest legal and ethical standards.', '', 18),

/* Printing */
('Hawkins Kappel', 'Head of Printing', 'Printing', 'Oversees the production and quality assurance of the magazine\'s physical publications.', 'He manages the print production cycle, liaising with vendors to ensure that every physical copy meets the magazine\'s high standards for quality, color accuracy, and timely delivery.', '', 19);
